/**
 * Build-time only: compiles scripts/aes-ige.wat into an embedded base64 string.
 * The generated file is part of the library; runtime needs no compiler, file,
 * or external package.
 */
import { readFileSync, writeFileSync } from "node:fs"
import { createRequire } from "node:module"

const require = createRequire(import.meta.url)
const factory = require("wabt")
const wabt = typeof factory === "function" ? await factory() : factory

const wat = readFileSync(new URL("./aes-ige.wat", import.meta.url), "utf8")
const module = wabt.parseWat("aes-ige.wat", wat, {})
const binary = Buffer.from(module.toBinary({ log: false, write_debug_names: false }).buffer)
module.destroy()

const out = `// GENERATED by scripts/build-embedded-wasm.mjs — do not edit.\n// Embedded AES-256-IGE WASM engine. No runtime dependencies.\nexport const EMBEDDED_WASM_BASE64 = ${JSON.stringify(binary.toString("base64"))}\n`
writeFileSync(new URL("../src/embedded-wasm.ts", import.meta.url), out)
// Cloudflare Workers forbid compiling WASM from bytes at runtime. Wrangler
// bundles a real .wasm import into a precompiled WebAssembly.Module, so ship
// the same binary as an asset for the Workers path.
writeFileSync(new URL("../src/aes-ige.wasm", import.meta.url), binary)
console.log(JSON.stringify({ ok: true, bytes: binary.length, base64Chars: out.length }))
